func DeliveryLoadMessageBodyRetain(r *TableRetainMessageReader, value *Delivery) bool {
	DeliveryReset(value)
	r.Retain.discard(r.Path, false, 0)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0x2bcee2fac7bb6eb5:
			{
				widened := false
				if entry.Shape.Kind != 17 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					index, ok := r.Bits.Get(r.IndexBits)
					if !ok || r.IndexBits <= 0 {
						r.Report.Malformed = true
						return false
					}
					r.Nodes.Resolve(&value.FriendName, index, 0x704be0d8faaffc58, &r.Report)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0xaf9dac3b097689c4:
			{
				widened := false
				if entry.Shape.Kind != 14 || entry.Element.Kind != 13 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					count, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if entry.Element.Kind == 6 && !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					holder := (*tableContainer)(unsafe.Pointer(&value.Cards))
					r.Retain.discard(r.Path, true, 1)
					if !tableContainerFill(&r.Nodes.Carve, holder, count, 312, 8) {
						r.Report.Malformed = true
						return false
					}
					holder.Count = 0
					element := TableMessageEntry{Shape: entry.Element}
					_ = element
					for i := uint64(0); i < count; i++ {
						p := (*DeliveryCardRow)(tableContainerFillAt(&r.Nodes.Carve, holder, int32(i), 312))
						if p == nil {
							r.Report.Malformed = true
							return false
						}
						holder.Count++
						{
							payload6 := r.Path
							r.Path = r.Path.step(1, uint32(i))
							if !DeliveryCardLoadMessageBodyRetain(r, &(*p)) {
								return false
							}
							r.Path = payload6
						}
					}
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !r.capture(entry) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func DeliverySaveMessageBody(w *TableMessageWriter, value *Delivery) bool {
	{
		if value.FriendName != 0 {
			w.Put(1, TableMessageRefBitsHere)
			if value.FriendName == 0 {
				w.Put(0, w.IndexBits)
			} else {
				index, ok := w.Numbering.Index(&value.FriendName)
				if !ok {
					return false
				}
				w.Put(index, w.IndexBits)
			}
		}
	}
	{
		if value.Cards.Count < 0 {
			return false
		}
		if value.Cards.Count > 0 {
			w.Put(2, TableMessageRefBitsHere)
			if value.Cards.Count < 0 {
				return false
			}
			w.Put(uint64(value.Cards.Count), 32)
			field := &DeliveryTableFields[1]
			if field.Kind == 6 {
				w.Align()
			}
			cursor := tableMapCursor((*tableContainer)(unsafe.Pointer(&value.Cards)), field, w.Numbering.arena)
			defer cursor.Release()
			for i := int32(0); i < value.Cards.Count; i++ {
				p := (*DeliveryCardRow)(cursor.Next())
				if p == nil {
					return false
				}
				if !DeliveryCardSaveMessageBody(w, &(*p)) {
					return false
				}
			}
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
